import {SKILLS,threshold,POWER_MILESTONES} from './progression.js';
import {AD_GAMES} from './ads-engine.js';
export function paintProgression(progression){const root=document.getElementById('skill-grid');if(!root)return;document.getElementById('growth-level').textContent='Lv.'+progression.totalLevel;document.getElementById('growth-save').textContent=progression.saved?`素材ボーナス ×${progression.multiplier} · 次 Lv.${POWER_MILESTONES.find(t=>t>progression.totalLevel)??'MAX'} · 保存済み`:'保存できません · このプレイ中のみ';root.innerHTML=AD_GAMES.map(game=>{const s=SKILLS.find(s=>s.id===game.id),total=progression.state.resources[s.id],level=progression.level(s.id),base=threshold(level),next=threshold(level+1),pct=level===10?100:(total-base)/(next-base)*100;return `<button class="skill-card" data-play="${s.id}" style="--skill:${s.color}" aria-label="${game.name}を遊ぶ。${s.name} レベル${level}"><span class="skill-icon">${s.icon}</span><span class="skill-name">${s.name}<small>${game.name}</small></span><strong>Lv.${level}</strong><span class="skill-effect">${s.effect(level)}</span><span class="skill-track"><i style="width:${pct}%"></i></span><span class="skill-material">${s.material} ${total}${level<10?' / '+next:' · MAX'}</span><span class="skill-play">PLAY ›</span></button>`;}).join('');}
